type Prioritas = "rendah" | "sedang" | "tinggi";
type Todo = { readonly id: number; judul: string; selesai: boolean; prioritas: Prioritas };
type Filter = "semua" | "aktif" | "selesai";

const daftar: Todo[] = [
  { id: 1, judul: "Belajar generics", selesai: false, prioritas: "sedang" },
  { id: 2, judul: "Beli kopi", selesai: true, prioritas: "rendah" },
  { id: 3, judul: "Kirim laporan", selesai: false, prioritas: "tinggi" },
  { id: 4, judul: "Review PR", selesai: false, prioritas: "tinggi" },
];
function saring(d: readonly Todo[], f: Filter): Todo[] {
  if (f === "aktif") return d.filter((t) => !t.selesai);
  if (f === "selesai") return d.filter((t) => t.selesai);
  return [...d];
}
const URUTAN: Record<Prioritas, number> = { tinggi: 0, sedang: 1, rendah: 2 };
function urutkanPrioritas(d: readonly Todo[]): Todo[] {
  return [...d].sort((a, b) => URUTAN[a.prioritas] - URUTAN[b.prioritas]);
}
console.log(saring(daftar, "aktif").map((t) => t.id).join(","));
console.log(urutkanPrioritas(daftar).map((t) => t.judul).join(" > "));

