type Todo = { readonly id: number; judul: string; selesai: boolean };
const daftar: Todo[] = [
  { id: 1, judul: "A", selesai: false },
  { id: 2, judul: "B", selesai: true },
  { id: 3, judul: "C", selesai: false },
  { id: 4, judul: "D", selesai: false },
];
function persenSelesai(d: readonly Todo[]): number {
  if (d.length === 0) return 0;
  return Math.round((d.filter((t) => t.selesai).length / d.length) * 100);
}
console.log(persenSelesai(daftar));
console.log(persenSelesai([]));
